   const shell=document.querySelector('.dashboard-shell'),inner=document.querySelector('.sidebar-drawer-inner'),side=document.querySelector('.workspace-sidebar')
   const captions=[...document.querySelectorAll(sidebarCaption?'.desktop-sidebar-controls':contentCaption?'.content-tabs > .desktop-drag':'.chatpane > .desktop-drag,.content-tabs > .desktop-drag')].filter(el=>el.getBoundingClientRect().width>1&&getComputedStyle(el).display!=='none'&&!el.closest('[inert],[aria-hidden="true"]'))
