   return{phase:shell.getAttribute('data-sidebar-phase'),sameCaption:probe.captionElement.isConnected&&contains(c,probe.captionPoint)&&!!captionHit&&probe.captionElement.contains(captionHit)&&!captionHit.closest('button,[role=tab],input,[data-no-drag],.content-tabs-viewport'),sameButton:probe.button.isConnected&&contains(b,probe.buttonPoint)&&!!buttonHit&&probe.button.contains(buttonHit),clipPointStillInLeakZone:!probe.clippedZone||(probe.captionPoint.x>side.right&&probe.captionPoint.x<side.left+inner.width),buttonRect:b.toJSON()}
